namespace sv_fa2ffb55791a48918a032b24eab15dfd.Client.Models;

public class StatusUpdate
{
    public DateTime Timestamp { get; set; }
    public string Status { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
}

public class Shipment
{
    public string TrackingNumber { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Models;

namespace sv_fa2ffb55791a48918a032b24eab15dfd.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Models;
using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Services;

namespace sv_fa2ffb55791a48918a032b24eab15dfd.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = DateTime.UtcNow.AddDays(2),
            StatusUpdates =
            [
                new() { Timestamp = DateTime.UtcNow.AddDays(-3), Status = "Order Placed", Location = "New York, NY" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-2), Status = "Picked Up", Location = "New York, NY" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-1), Status = "In Transit", Location = "Chicago, IL" },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = DateTime.UtcNow.AddDays(-1),
            StatusUpdates =
            [
                new() { Timestamp = DateTime.UtcNow.AddDays(-5), Status = "Order Placed", Location = "Seattle, WA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-4), Status = "Picked Up", Location = "Seattle, WA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-3), Status = "In Transit", Location = "Portland, OR" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-2), Status = "Out for Delivery", Location = "San Francisco, CA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-1), Status = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = DateTime.UtcNow.AddDays(5),
            StatusUpdates =
            [
                new() { Timestamp = DateTime.UtcNow.AddHours(-6), Status = "Order Placed", Location = "Dallas, TX" },
                new() { Timestamp = DateTime.UtcNow.AddHours(-1), Status = "Processing", Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

using System.Net.Http.Json;
using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Models;

namespace sv_fa2ffb55791a48918a032b24eab15dfd.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var shipment = await http.GetFromJsonAsync<Shipment>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        return shipment ?? throw new InvalidOperationException("Received null shipment from API.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Models
@using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracking</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            @if (_shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.Value.ToString("f")</p>
            }
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h5>Status History</h5>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Status</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Status</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — nothing to show.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

