                new() { Timestamp = DateTime.UtcNow.AddDays(-2), Status = "Out for Delivery", Location = "San Francisco, CA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-1), Status = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["PKG-003"] = new Shipment
