using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Models;
using sv_fa2ffb55791a48918a032b24eab15dfd.Client.Services;

namespace sv_fa2ffb55791a48918a032b24eab15dfd.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = DateTime.UtcNow.AddDays(2),
            StatusUpdates =
            [
                new() { Timestamp = DateTime.UtcNow.AddDays(-3), Status = "Order Placed", Location = "New York, NY" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-2), Status = "Picked Up", Location = "New York, NY" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-1), Status = "In Transit", Location = "Chicago, IL" },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = DateTime.UtcNow.AddDays(-1),
            StatusUpdates =
            [
                new() { Timestamp = DateTime.UtcNow.AddDays(-5), Status = "Order Placed", Location = "Seattle, WA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-4), Status = "Picked Up", Location = "Seattle, WA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-3), Status = "In Transit", Location = "Portland, OR" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-2), Status = "Out for Delivery", Location = "San Francisco, CA" },
                new() { Timestamp = DateTime.UtcNow.AddDays(-1), Status = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = DateTime.UtcNow.AddDays(5),
            StatusUpdates =
            [
                new() { Timestamp = DateTime.UtcNow.AddHours(-6), Status = "Order Placed", Location = "Dallas, TX" },
                new() { Timestamp = DateTime.UtcNow.AddHours(-1), Status = "Processing", Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

